import re

_TITLE_RE = re.compile(
    r"<title>(.*?)</title>",
    re.IGNORECASE | re.DOTALL | re.ASCII,
)


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the next `</title>`.

    The tag names are matched case-insensitively. The text is returned
    verbatim: it is not stripped and HTML entities are not decoded.
    Returns "" if there is no `<title>`, or if it is never closed.
    """
    m = _TITLE_RE.search(html)
    if m is None:
        return ""
    return m.group(1)


def test_basic() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>hi</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_unclosed_title() -> None:
    assert title_of("<html><title>Oops") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HEAD><TITLE>Mixed</Title></HEAD>") == "Mixed"


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced \n out </title>") == "  spaced \n out "


def test_entities_not_decoded() -> None:
    assert title_of("<title>a &amp; b</title>") == "a &amp; b"


def test_closing_tag_before_opening_ignored() -> None:
    assert title_of("</title><title>Real</title>") == "Real"


def test_unicode() -> None:
    assert title_of("<title>Café ☕</title>") == "Café ☕"
